package org.eclipse.rdf4j.query.algebra.evaluation.iterator;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.util.function.Function;

import org.eclipse.rdf4j.model.impl.BooleanLiteral;
import org.eclipse.rdf4j.query.QueryEvaluationException;
import org.eclipse.rdf4j.query.algebra.Filter;
import org.eclipse.rdf4j.query.algebra.SingletonSet;
import org.eclipse.rdf4j.query.algebra.Var;
import org.eclipse.rdf4j.query.algebra.evaluation.QueryValueEvaluationStep;
import org.eclipse.rdf4j.query.algebra.evaluation.ValueExprEvaluationException;
import org.eclipse.rdf4j.query.algebra.evaluation.impl.DefaultEvaluationStrategy;
import org.eclipse.rdf4j.query.algebra.evaluation.impl.EmptyTripleSource;
import org.eclipse.rdf4j.query.algebra.evaluation.impl.EvaluationStatistics;
import org.eclipse.rdf4j.query.explanation.TelemetryMetricNames;
import org.eclipse.rdf4j.query.impl.EmptyBindingSet;
import org.junit.jupiter.api.Test;

class FilterConditionTelemetryTest {

	private final DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(new EmptyTripleSource(), null);

	@Test
	void measuredTrueFalseAndExpressionErrorPublishOnce() {
		Filter filter = filter(true);
		FilterCondition condition = new FilterCondition(filter, null);
		assertThat(evaluate(condition, value(true), true)).isTrue();
		assertThat(evaluate(condition, value(false), true)).isFalse();
		assertThat(evaluate(condition, ignored -> {
			throw new ValueExprEvaluationException("invalid effective boolean value");
		}, true)).isFalse();
		condition.close();
		condition.close();
		assertPopulation(filter, 3, 1, 2);
		assertThat(filter.getLongMetricActual(TelemetryMetricNames.EXPR_EVAL_COUNT_ACTUAL)).isEqualTo(3);
		assertThat(filter.getLongMetricActual(TelemetryMetricNames.EXPR_TRUE_COUNT_ACTUAL)).isEqualTo(1);
		assertThat(filter.getLongMetricActual(TelemetryMetricNames.EXPR_FALSE_COUNT_ACTUAL)).isEqualTo(1);
		assertThat(filter.getLongMetricActual(TelemetryMetricNames.PREDICATE_ERROR_COUNT_ACTUAL)).isEqualTo(1);
	}

	@Test
	void emptyMeasuredPopulationPublishesKnownZero() {
		Filter filter = filter(true);
		new FilterCondition(filter, null).close();
		assertPopulation(filter, 0, 0, 0);
	}

	@Test
	void telemetryDisabledLeavesPopulationUnknown() {
		Filter filter = filter(false);
		FilterCondition condition = new FilterCondition(filter, null);
		assertThat(evaluate(condition, value(true), true)).isTrue();
		condition.close();
		assertPopulation(filter, -1, -1, -1);
		assertThat(filter.getLongMetricActual(TelemetryMetricNames.EXPR_EVAL_COUNT_ACTUAL)).isEqualTo(-1);
	}

	@Test
	void movedPopulationMeasuresWorkWithoutStaticSelectivityFeedback() {
		Filter filter = filter(true);
		long[] recorded = new long[2];
		EvaluationStatistics statistics = new EvaluationStatistics() {
			@Override
			public void recordFilterOutcome(Filter observed, long passed, long filtered) {
				recorded[0] += passed;
				recorded[1] += filtered;
			}
		};
		FilterCondition condition = new FilterCondition(filter, statistics);
		assertThat(evaluate(condition, value(true), false)).isTrue();
		assertThat(evaluate(condition, value(false), false)).isFalse();
		condition.close();
		assertPopulation(filter, 2, 1, 1);
		assertThat(recorded).containsExactly(0, 0);
	}

	@Test
	void onlyOriginalPopulationUpdatesStaticSelectivity() {
		Filter filter = filter(true);
		long[] recorded = new long[2];
		EvaluationStatistics statistics = new EvaluationStatistics() {
			@Override
			public void recordFilterOutcome(Filter observed, long passed, long filtered) {
				recorded[0] += passed;
				recorded[1] += filtered;
			}
		};
		FilterCondition condition = new FilterCondition(filter, statistics);
		evaluate(condition, value(true), true);
		evaluate(condition, value(false), true);
		evaluate(condition, value(false), false);
		condition.close();
		assertPopulation(filter, 3, 1, 2);
		assertThat(recorded).containsExactly(1, 1);
	}

	@Test
	void repeatedInvocationsAccumulateTheirOwnMeasuredPopulation() {
		Filter filter = filter(true);
		FilterCondition first = new FilterCondition(filter, null);
		evaluate(first, value(true), true);
		evaluate(first, value(false), true);
		first.close();
		FilterCondition second = new FilterCondition(filter, null);
		evaluate(second, value(true), true);
		second.close();
		first.close();
		second.close();
		assertPopulation(filter, 3, 2, 1);
	}

	@Test
	void unexpectedFailurePropagatesAndCleanupPublishesPartialWork() {
		Filter filter = filter(true);
		FilterCondition condition = new FilterCondition(filter, null);
		evaluate(condition, value(true), true);
		assertThatThrownBy(() -> evaluate(condition, ignored -> {
			throw new QueryEvaluationException("unexpected predicate failure");
		}, true)).isInstanceOf(QueryEvaluationException.class).hasMessage("unexpected predicate failure");
		condition.close();
		condition.close();
		assertPopulation(filter, 2, 1, 0);
		assertThat(filter.getLongMetricActual(TelemetryMetricNames.PREDICATE_ERROR_COUNT_ACTUAL)).isZero();
	}

	private boolean evaluate(FilterCondition condition, QueryValueEvaluationStep expression, boolean original) {
		return condition.evaluate(expression, strategy, Function.identity(), EmptyBindingSet.getInstance(), original);
	}

	private static QueryValueEvaluationStep value(boolean value) {
		return ignored -> BooleanLiteral.valueOf(value);
	}

	private static Filter filter(boolean telemetry) {
		Filter filter = new Filter(new SingletonSet(), new Var("condition"));
		filter.setRuntimeTelemetryEnabled(telemetry);
		return filter;
	}

	private static void assertPopulation(Filter filter, long scanned, long matched, long filtered) {
		assertThat(filter.getSourceRowsScannedActual()).as("tested condition inputs").isEqualTo(scanned);
		assertThat(filter.getSourceRowsMatchedActual()).as("accepted condition inputs").isEqualTo(matched);
		assertThat(filter.getSourceRowsFilteredActual()).as("false or expression-error inputs").isEqualTo(filtered);
	}
}
